cat > outputs/app/app.js <<'"'EOF'
'use strict';
const d=window.EVAL_FIXTURES.dashboard;
const screen=['live','stale','surge'].includes(params.get('screen'))?params.get('screen'):'live';
const tv=document.documentElement.dataset.display==='tv', stale=screen==='stale';
const active=d.incidents.slice(0,screen==='surge'?d.surgeCount:d.openCount);
let current='open',query='',severity='all',page=0;
const e=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
const person=(label,value)=>{const [name,role]=value.split(' (');return "'`<div class="person"><div class="person-label">${label}</div><strong>${e(name)}</strong><div class="person-role">${e(role.replace('"')',''))}</div></div>"'`};
document.querySelector('"'#app').innerHTML="'`
<header class="topbar"><div class="brand"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M16 2 28 28 16 22 4 28 16 2Z" stroke="currentColor" stroke-width="2"/><path d="M16 8v14M11 19l10-4" stroke="currentColor" stroke-width="2"/></svg><span>Northwind</span><small>Operations</small></div><div class="clock"><span>${e(d.displayDate)}</span><strong class="mono">${e(d.displayTime)}</strong></div></header>
<main class="shell"><div class="titlebar"><h1>Incident overview</h1><div class="freshness">${stale?`<span class="fresh-label" style="color:var(--caution)">Updates interrupted</span><span>Last received ${e(d.staleAsOf)}</span>`:`<span class="fresh-label"><span class="dot"></span>Live snapshot</span><span>As of ${e(d.displayTime)}</span>`}</div></div>
${stale?`<div class="stale-warning" role="status"><strong>Data is stale · last received ${e(d.staleAsOf)}</strong><span>Updates are unavailable. Counts, statuses and durations may have changed; confirm with the on-call team.</span></div>`:'"''}
<section class=\"metrics\" aria-label=\"Incident metrics"'${stale?'"', last known values':''}\"><div class=\"metric\"><div class=\"metric-label\">"'${stale?'"'Last known open incidents':'Open incidents'}</div><div class=\"metric-number\" id=\"open\">"'${active.length}</div><div class="metric-note"><strong>1 SEV1</strong> · 2 SEV2 · ${active.length-3} SEV3</div></div><div class="metric"><div class="metric-label">Mean time to resolve · 7d</div><div class="metric-number">${e(d.mttr)}</div><div class="metric-note good">↓ ${e(d.mttrChange)} vs last week</div></div><div class="metric"><div class="metric-label">Pages today</div><div class="metric-number">${d.pages}</div><div class="metric-note">↑ ${d.pagesDelta} vs yesterday</div></div><div class="metric"><div class="metric-label">SLO budget left</div><div class="metric-number">${e(d.slo)}</div><div class="metric-note">↓ ${e(d.sloChange)}</div></div></section>
<div class="workspace"><section class="board" id="incidents" aria-label="Incident list" tabindex="-1"><div class="board-heading"><div class="tabs" role="group" aria-label="Incident view"><button class="tab" id="open-tab" aria-pressed="true">Open incidents <span class="count">${active.length}</span></button><button class="tab" id="resolved-tab" aria-pressed="false">Resolved <span class="count">${d.resolved.length}</span></button></div></div><div class="tools"><label class="sr-only" for="search">Search incidents</label><input id="search" type="search" placeholder="Search incidents" autocomplete="off"><label class="sr-only" for="severity">Filter by severity</label><select id="severity"><option value="all">All severities</option><option value="1">SEV1</option><option value="2">SEV2</option><option value="3">SEV3</option></select><span class="list-note">Mitigated and monitoring remain open.</span></div><div id="results"></div></section>
<aside class="sidebar" aria-label="Operational context"><section class="side-section"><div class="section-head"><h2>On call now</h2><span>Until ${e(d.until)}</span></div>${person('"'Primary',d.primary)}"'${person('"'Secondary',d.secondary)}<div class=\"ownership\"><span>Incident commander</span><strong>Unassigned</strong><p>SEV1 · INC-2291 has no commander.</p></div></section><section class=\"side-section\"><div class=\"section-head\"><h2>Incidents by service</h2><span>30 days</span></div>"'${d.services.map(s=>`<div class="service"><div class="service-label"><span>${e(s.name)}</span><span class="mono">${s.value}</span></div><div class="track" aria-hidden="true"><div class="bar" style="width:${s.value/d.services[0].value*100}%"></div></div></div>`).join('"'')}<p class=\"chart-caption\">"'${d.services.reduce((n,s)=>n+s.value,0)} incidents across ${d.services.length} services.</p></section></aside></div>
<footer class="page-footer"><span>Northwind Logistics · Incident metrics</span><span>${stale?'"'Last known snapshot':'Snapshot'} · "'${e(d.displayDate)}</span></footer></main>
<dialog aria-labelledby="detail-title"><div class="dialog-head"><span id="detail-id" class="mono muted"></span><button id="close-dialog" aria-label="Close incident details">Close <span aria-hidden="true">×</span></button></div><h2 id="detail-title"></h2><dl id="detail-facts"></dl></dialog><div class="sr-only" id="announcement" role="status" aria-live="polite"></div>`;
function render(){
 const source=current==='"'open'?active:d.resolved;
 const list=source.filter(i=>(severity==='all'||i.severity===Number(severity))&&("'`${i.id} ${i.title} ${i.service} ${i.status} ${i.commander||'"'unassigned'}"'`).toLowerCase().includes(query.toLowerCase()));
 const start=tv?page*7:0,visible=tv?list.slice(start,start+7):list;
 document.querySelector('"'#results').innerHTML=list.length?"'`<div class="table-wrap"><table><caption>${current==='"'open'?'Open':'Resolved'} incidents. Durations and opened times are supplied snapshot values"'${stale?'"', data is stale':''}.</caption><colgroup><col class=\"sev-col\"><col class=\"incident-col\"><col class=\"status-col\"><col class=\"owner-col\"><col class=\"age-col\"></colgroup><thead><tr><th scope=\"col\">Severity</th><th scope=\"col\">Incident / service</th><th scope=\"col\">Status</th><th scope=\"col\">Commander</th><th scope=\"col\">Duration / opened</th></tr></thead><tbody>"'${visible.map(i=>`<tr class="${i.severity===1?'"'critical-row':''}\"><td><span class=\"severity sev"'${i.severity}">SEV${i.severity}</span></td><td><button class="incident-link" data-incident="${i.id}">${e(i.title)}<span class="incident-meta"><span class="mono">${i.id}</span> · ${e(i.service)}</span></button></td><td><span class="status">${e(i.status)}</span></td><td class="${i.commander===null?'"'missing':''}\">"'${i.commander===null?'"'Unassigned':e(i.commander||'—')}</td><td><span class=\"age\">"'${e(i.duration)}</span><span class="opened">${e(i.opened)}</span></td></tr>`).join('"'')}</tbody></table></div><div class=\"board-footer\"><span>"'${tv&&list.length>7?`Showing ${start+1}–${Math.min(start+7,list.length)} of ${list.length} · ${page===0?'"'5 more on the next page':'continued from page 1'}"'`:`${list.length} ${current==='"'open'?'open':'resolved'} incident"'${list.length===1?'"'':'s'}"'${query||severity!=='"'all'?' matching filters':current==='open'?' · includes mitigated and monitoring':''}"'`}</span>${tv&&list.length>7?`<div class="paging"><button id="prev" ${page===0?'"'disabled':''} aria-label=\"Previous incident page\">← Previous</button><button id=\"next\" "'${start+7>=list.length?'"'disabled':''} aria-label=\"Next incident page\">Next →</button></div>"'`:'"''}</div>"'`:`<div class="empty"><strong>No matching incidents</strong><p>Try another search or severity.</p><button id="clear-filters">Clear filters</button></div>`;
 document.querySelectorAll('"'[data-incident]').forEach(b=>b.addEventListener('click',()=>showIncident(b.dataset.incident)));
 document.querySelector('#next')?.addEventListener('click',()=>{page++;render();document.querySelector('#prev')?.focus();announce('Incident page 2 of 2')});
 document.querySelector('#prev')?.addEventListener('click',()=>{page--;render();document.querySelector('#next')?.focus();announce('Incident page 1 of 2')});
 document.querySelector('#clear-filters')?.addEventListener('click',()=>{query='';severity='all';document.querySelector('#search').value='';document.querySelector('#severity').value='all';render();document.querySelector('#search').focus()});
}
function announce(s){document.querySelector('#announcement').textContent=s}
function switchView(view){current=view;page=0;document.querySelector('#open-tab').setAttribute('aria-pressed',String(view==='open'));document.querySelector('#resolved-tab').setAttribute('aria-pressed',String(view==='resolved'));render();announce("'`${view==='"'open'?'Open':'Resolved'} incidents selected"'`)}
document.querySelector('"'#open-tab').addEventListener('click',()=>switchView('open'));
document.querySelector('#resolved-tab').addEventListener('click',()=>switchView('resolved'));
